stack_clear();
stack_push(1);
stack_push(2);
int v;
stack_pop(&v);
CHECK_EQ(v, 2);

stack_clear();
for (int i = 0; i < 16; i++) stack_push(i);
CHECK_EQ(stack_push(99), 0);
CHECK_EQ(stack_size(), 16);

stack_clear();
stack_push(4);
int v;
CHECK_EQ(stack_top(&v), 1);
CHECK_EQ(v, 4);
CHECK_EQ(stack_size(), 1);
